export type StatfsFn = (path: string) => { type: number | bigint };

/**
 * Probes the filesystem type of `path`. Refuses (throws) unless the magic is in
 * LOCAL_FS_MAGICS — remote magics get a named error, unknown magics are refused too
 * (default-deny: "we could not prove O_APPEND atomicity here" is a reason to stop,
 * not a reason to hope). GAP-060 condition ①.
 */
export function assertLocalFilesystem(path: string, statfs: StatfsFn = statfsSync): FsProbe {
	const raw = statfs(path).type;
	const magic = typeof raw === "bigint" ? raw : BigInt(raw >>> 0);
	const hex = `0x${magic.toString(16)}`;
	const localName = LOCAL_FS_MAGICS.get(magic);
	if (localName) return { path, fsTypeHex: hex, fsName: localName, local: true };
	const remoteName = REMOTE_FS_MAGICS.get(magic);
	if (remoteName) {
		throw new LedgerFilesystemError(
			`k3 ledger refuses to start: ${path} is on ${remoteName} (f_type=${hex}). ` +
				`O_APPEND append atomicity does not hold on network filesystems (Linux NFS FAQ A9); ` +
				`the ledger's no-torn-line guarantee would be void. Move k3/ledger to a local filesystem.`,
			hex,
			remoteName,
		);
	}
	throw new LedgerFilesystemError(
		`k3 ledger refuses to start: ${path} has unknown f_type=${hex}. ` +
			`Default-deny: O_APPEND atomicity is only trusted on known-local filesystems ` +
			`(${[...LOCAL_FS_MAGICS.values()].join(", ")}). Register the magic if it is local.`,
		hex,
		undefined,
	);
}

