function base32(buf: Buffer, chars: number): string {
	let bits = 0;
	let value = 0;
	let out = "";
	for (const byte of buf) {
		value = (value << 8) | byte;
		bits += 8;
		while (bits >= 5 && out.length < chars) {
			out += B32_ALPHABET[(value >>> (bits - 5)) & 31];
			bits -= 5;
		}
		if (out.length >= chars) break;
	}
	return out;
}

