/**
 * Verifies the hash chain of a ledger directory. Detection, not prevention (§4.1.3: the
 * single-user threat model is "my own bugs", not adversaries); returns the first break.
 */
export function verifyChain(
	dir: string,
	stem = "events",
): { ok: boolean; rows: number; brokenAtSeq?: number; reason?: string } {
	const files = readdirSync(dir)
		.filter((f) => f.startsWith(`${stem}-`) && f.endsWith(".jsonl"))
		.sort();
	let prevHash = "sha256:genesis";
	let rows = 0;
	for (const file of files) {
		const text = readFileSync(join(dir, file), "utf8");
		for (const line of text.split("\n")) {
			if (line.trim().length === 0) continue;
			let row: LedgerRow;
			try {
				row = JSON.parse(line) as LedgerRow;
			} catch {
				return { ok: false, rows, reason: `unparseable line after seq ${rows}` };
			}
			if (row.prev_hash !== prevHash) {
				return { ok: false, rows, brokenAtSeq: row.seq, reason: "prev_hash mismatch (chain break)" };
			}
			prevHash = `sha256:${sha256hex(line)}`;
			rows++;
		}
	}
	return { ok: true, rows };
}

