 * §4.1.6 (d): billing sits AFTER dedup and BEFORE the side effect. A dedup hit returns the
 * cached result and consumes NO quota (upstream ordering was tryConsume-first with refund on
 * throw, which silently billed accepted-but-unconfirmed attempts).
 */
export function dedupThenConsume<T>(
	ledger: EventLedger,
	idemKey: string,
	tryConsume: () => boolean,
	execute: () => T,
	record: (result: T) => LedgerEventInput,
): { outcome: SubmitOutcome; cached: boolean; seq?: number } {
	const seen = ledger.query(idemKey);
	if (seen) return { outcome: K3_ACCEPTED, cached: true, seq: seen.seq };
	if (!tryConsume()) return { outcome: K3_NOT_ACCEPTED, cached: false };
	const result = execute();
	const appended = ledger.append({ ...record(result), idem_key: idemKey });
	return { outcome: appended.outcome, cached: false, seq: appended.seq };
}

