	const base: EventLedgerOptions = { dir: options.dir, now: options.now, statfs: options.statfs };
	const events = new EventLedger(base);
	const evidence = new EvidenceLedger(base);
	return { events, evidence, boundarySink: createBoundarySink(events) };
}

