/**
 * Rebuilds the metrics materialized view from the primary. The view lives under
 * `projections/` and may be deleted at any time — `rm -rf` + this function is the documented
 * lifecycle (event-sourcing "projections are disposable" principle). v10 materializes to JSON,
 * not DuckDB, under the §4.1.10 deprecation clause (zero-dep while queries stay fast).
 */
export function rebuildMetricsView(dir: string, stem = "events", now: () => number = Date.now): MetricsView {
	const byType: Record<string, number> = {};
	const byPhase: Record<string, number> = {};
	let rows = 0;
	let failKills = 0;
	for (const row of scanLedger(dir, () => true, stem)) {
		rows++;
		byType[row.event_type] = (byType[row.event_type] ?? 0) + 1;
		if (row.phase) byPhase[row.phase] = (byPhase[row.phase] ?? 0) + 1;
		if (
			row.event_type === "gate.decision" &&
			(row.payload as Record<string, unknown> | null)?.verdict === "FAIL-KILL"
		) {
			failKills++;
		}
	}
	const view: MetricsView = {
		rebuilt_at: new Date(now()).toISOString(),
		source_rows: rows,
		by_event_type: byType,
		by_phase: byPhase,
		fail_kills: failKills,
	};
	const projDir = join(dir, "projections");
	mkdirSync(projDir, { recursive: true });
	// Derived file, not the ledger: atomic replace via tmp+rename is the correct primitive here
	// (overwrite-in-place is the read-torn pathology; the ledger itself never uses this path).
	const tmp = join(projDir, ".metrics.json.tmp");
	writeFileSync(tmp, JSON.stringify(view), "utf8");
	renameSync(tmp, join(projDir, "metrics.json"));
	return view;
}

