verifyShadowConsistency(
	dir: string,
	pointers: readonly ShadowPointer[],
	stem = "events",
): ConsistencyReport {
	const bySeq = new Map<number, LedgerRow>();
	for (const row of scanLedger(dir, () => true, stem)) bySeq.set(row.seq, row);
	const pointerSeqs = new Map<number, ShadowPointer>();
	const dangling: number[] = [];
	for (const ptr of pointers) {
		const row = bySeq.get(ptr.seq);
		if (!row || row.event_id !== ptr.event_id || row.event_type !== ptr.event_type) dangling.push(ptr.seq);
		else pointerSeqs.set(ptr.seq, ptr);
	}
	const missing: number[] = [];
	for (const seq of bySeq.keys()) {
		if (!pointerSeqs.has(seq)) missing.push(seq);
	}
	missing.sort((a, b) => a - b);
	dangling.sort((a, b) => a - b);
	return {
		consistent: missing.length === 0 && dangling.length === 0,
		missingPointers: missing,
		danglingPointers: dangling,
		ledgerRows: bySeq.size,
		shadowPointers: pointers.length,
	};
}

/** Re-projects the whole primary into fresh shadow entries (the repair path for an inconsistent shadow). */
export function reprojectAll(dir: string, ledgerFile: string, sinks: ShadowSinks, stem = "events"): number {
	let count = 0;
	for (const row of scanLedger(dir, () => true, stem)) {
		projectEvent(row, ledgerFile, sinks);
		count++;
	}
	return count;
}

