describe("upgrade seam · session derivation (forkFrom / branch)", () => {
	it("forkFrom copies the source history into an independent session file", () => {
		const source = SessionManager.create(root, join(root, "src-sessions"));
		source.appendMessage({ role: "user", content: "seed question", timestamp: Date.now() });
		source.appendMessage(assistantMessage("seed answer"));
		const sourceFile = source.getSessionFile();
		expect(sourceFile).toBeDefined();

		const fork = SessionManager.forkFrom(sourceFile as string, root, join(root, "fork-sessions"));
		const forked = fork.getEntries();
		expect(JSON.stringify(forked)).toContain("seed question");
		expect(JSON.stringify(forked)).toContain("seed answer");

		// Derivation is isolation: writing to the fork must not touch the source.
		fork.appendMessage({ role: "user", content: "fork-only turn", timestamp: Date.now() });
		const reread = SessionManager.open(sourceFile as string, join(root, "src-sessions"));
		expect(JSON.stringify(reread.getEntries())).not.toContain("fork-only turn");
	});

	it("branchWithSummary moves the leaf without deleting any entry (append-only tree)", () => {
		const manager = SessionManager.create(root, join(root, "branch-sessions"));
		const forkPointId = manager.appendMessage({ role: "user", content: "turn A", timestamp: Date.now() });
		manager.appendMessage(assistantMessage("answer A"));
		manager.appendMessage({ role: "user", content: "turn B (to be branched away)", timestamp: Date.now() });
		const before = manager.getEntries().length;

		manager.branchWithSummary(forkPointId, "summary of the abandoned tip");

		// Nothing was deleted: the abandoned tip and the new summary both live in the entry set
		// (append-only tree — the G7 lineage seam). getEntries() exposes the full file entry set.
		const all = JSON.stringify(manager.getEntries());
		expect(all).toContain("turn B (to be branched away)");
		expect(all).toContain("summary of the abandoned tip");
		expect(manager.getEntries().length).toBeGreaterThan(before);
	});
});

